// The docs site's only script: the search box in the top bar, and one
// courtesy for the sidebar.
//
// It is progressive by construction. The box is a real <form> whose
// action searches the repository on GitHub, so with this file blocked
// — or before it loads — typing and pressing Enter still answers. When
// it does run, the form stops submitting and answers locally instead,
// from search.json: one entry per page carrying its title, its section
// and its headings, fetched once on the first keystroke.
//
// The index is generated by scripts/gen-site.janet next to the pages,
// so it cannot drift from them.

(function () {
  'use strict';

  var here = document.currentScript && document.currentScript.src;
  var root = here ? new URL('.', here) : new URL('.', location.href);

  // The sidebar unfolds forty-odd children under the section a reader
  // is in, and the one they are reading can be far down that list.
  // Scroll it into the middle of the rail — of the rail alone, which
  // is why this is arithmetic rather than scrollIntoView.
  var side = document.querySelector('nav.side');
  var current = side && side.querySelector('ul.side-sub a.here');
  if (side && current && side.scrollHeight > side.clientHeight) {
    side.scrollTop = current.offsetTop - side.clientHeight / 2;
  }

  var form = document.querySelector('form.search');
  var input = document.getElementById('q');
  var box = document.getElementById('results');
  if (!form || !input || !box) return;

  var index = null;      // the fetched pages, or null until asked for
  var loading = null;    // the in-flight fetch, so a fast typist gets one
  var rows = [];         // what is currently on screen
  var sel = -1;

  function load() {
    if (index) return Promise.resolve(index);
    if (loading) return loading;
    loading = fetch(new URL('search.json', root).href)
      .then(function (r) { return r.ok ? r.json() : []; })
      .then(function (j) { index = j; return j; })
      .catch(function () { index = []; return index; });
    return loading;
  }

  // -- matching ---------------------------------------------------------
  //
  // Every term must appear somewhere in the entry; where it appears is
  // what ranks it. A heading hit becomes its own row, so a search for a
  // binding lands on the section rather than the top of a 110 KB page.

  function terms(q) {
    return q.toLowerCase().split(/\s+/).filter(Boolean);
  }

  function hit(hay, ts) {
    for (var i = 0; i < ts.length; i++) if (hay.indexOf(ts[i]) < 0) return false;
    return true;
  }

  function search(q) {
    var ts = terms(q);
    if (!ts.length) return [];
    var out = [];
    (index || []).forEach(function (p) {
      var title = (p.t || '').toLowerCase();
      var text = (p.x || '').toLowerCase();
      if (hit(title, ts)) {
        out.push({ score: 100 - title.length, page: p, title: p.t, url: p.u });
      } else if (hit(title + ' ' + text, ts)) {
        out.push({ score: 40 - title.length, page: p, title: p.t, url: p.u });
      }
      (p.h || []).forEach(function (h) {
        var ht = h.t.toLowerCase();
        if (!hit(ht, ts)) return;
        // an exact heading is what the reader most often means
        var exact = ht === ts.join(' ');
        out.push({
          score: (exact ? 200 : 70) - h.t.length,
          page: p, title: h.t, where: p.n || p.t, url: p.u + '#' + h.i
        });
      });
    });
    out.sort(function (a, b) { return b.score - a.score; });
    return out.slice(0, 24);
  }

  // -- rendering --------------------------------------------------------

  function marked(text, ts) {
    var frag = document.createDocumentFragment();
    var low = text.toLowerCase();
    var at = ts.length ? low.indexOf(ts[0]) : -1;
    if (at < 0) { frag.appendChild(document.createTextNode(text)); return frag; }
    frag.appendChild(document.createTextNode(text.slice(0, at)));
    var m = document.createElement('mark');
    m.textContent = text.slice(at, at + ts[0].length);
    frag.appendChild(m);
    frag.appendChild(document.createTextNode(text.slice(at + ts[0].length)));
    return frag;
  }

  function paint(q) {
    var ts = terms(q);
    rows = search(q);
    box.textContent = '';
    sel = rows.length ? 0 : -1;
    if (!q) { box.hidden = true; return; }
    if (!rows.length) {
      var none = document.createElement('div');
      none.className = 'r-none';
      none.textContent = 'Nothing here — press Enter to search the repository.';
      box.appendChild(none);
      box.hidden = false;
      return;
    }
    rows.forEach(function (r, i) {
      var a = document.createElement('a');
      a.href = new URL(r.url, root).href;
      if (i === 0) a.className = 'sel';
      var t = document.createElement('div');
      t.className = 'r-title';
      t.appendChild(marked(r.title, ts));
      a.appendChild(t);
      var w = document.createElement('div');
      w.className = 'r-where';
      w.textContent = r.where || r.page.s || '';
      a.appendChild(w);
      box.appendChild(a);
      r.el = a;
    });
    box.hidden = false;
  }

  function move(step) {
    if (!rows.length) return;
    if (sel >= 0) rows[sel].el.classList.remove('sel');
    sel = (sel + step + rows.length) % rows.length;
    rows[sel].el.classList.add('sel');
    rows[sel].el.scrollIntoView({ block: 'nearest' });
  }

  function close() { box.hidden = true; }

  // -- wiring -----------------------------------------------------------

  input.addEventListener('input', function () {
    var q = input.value;
    load().then(function () { if (input.value === q) paint(q); });
  });
  input.addEventListener('focus', load);
  input.addEventListener('blur', function () {
    // let a click on a result land before the box goes away
    setTimeout(close, 150);
  });

  input.addEventListener('keydown', function (e) {
    if (e.key === 'ArrowDown') { e.preventDefault(); move(1); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); move(-1); }
    else if (e.key === 'Escape') { close(); input.blur(); }
  });

  form.addEventListener('submit', function (e) {
    // a chosen result wins; with nothing to choose the form goes to
    // GitHub, which is what it does without this script at all
    if (sel >= 0 && rows[sel]) { e.preventDefault(); rows[sel].el.click(); }
  });

  document.addEventListener('keydown', function (e) {
    var typing = /^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement.tagName);
    var slash = e.key === '/' && !typing && !e.metaKey && !e.ctrlKey;
    var kbd = (e.key === 'k' || e.key === 'K') && (e.metaKey || e.ctrlKey);
    if (slash || kbd) { e.preventDefault(); input.focus(); input.select(); }
  });

  input.placeholder = 'Search the docs…  /';
})();
